# Tool Name: detect_encryption_algorithm
# Description: Detects the encryption algorithm from a key prefix and returns the algorithm name, key size, and the actual cryptographic key bytes.
# Arguments: key (bytes) - The full key with prefix (e.g., b"aes-256-cbc:" + actual_key_bytes)
# Returns: A tuple of (algorithm_name, key_size, actual_key_bytes)
# Requires: None
def detect_encryption_algorithm(key):
    # Define supported algorithms and their required key sizes in bytes
    algorithm_prefixes = {
        "aes-128-cbc:": ("aes-128-cbc", 16),
        "aes-192-cbc:": ("aes-192-cbc", 24),
        "aes-256-cbc:": ("aes-256-cbc", 32),
    }

    # Convert bytes to string for prefix matching
    if isinstance(key, bytes):
        # Check each prefix to find a match
        for prefix, (algo_name, key_size) in algorithm_prefixes.items():
            prefix_bytes = prefix.encode('utf-8')
            if key.startswith(prefix_bytes):
                actual_key = key[len(prefix_bytes):]
                if len(actual_key) != key_size:
                    raise ValueError(
                        f"Key length mismatch for {algo_name}: expected {key_size} bytes, got {len(actual_key)} bytes."
                    )
                return algo_name, key_size, actual_key
        raise ValueError(
            f"No valid algorithm prefix found in key. Supported prefixes: {list(algorithm_prefixes.keys())}"
        )
    else:
        raise TypeError("Key must be of type bytes.")

# Test the function
test_key = b"aes-256-cbc:" + b"0" * 32
result = detect_encryption_algorithm(test_key)
print(result)

# Tool Name: yaml_file_to_json
# Description: Reads a YAML file from the given path and converts its content to a JSON string. Returns an error message starting with "Error: " on failure.
# Arguments: file_path (str) - The path to the YAML file.
# Returns: str - JSON string on success, or error message starting with "Error: " on failure.
# Requires: PyYAML (yaml), json, os
def yaml_file_to_json(file_path):
    import yaml
    import json

    # Step 2: File Reading with Error Handling
    try:
        if not os.path.isfile(file_path):
            return f"Error: File not found at '{file_path}'"
        with open(file_path, 'r', encoding='utf-8') as f:
            yaml_content = f.read()
    except FileNotFoundError:
        return f"Error: File not found at '{file_path}'"
    except PermissionError:
        return f"Error: Permission denied when reading file at '{file_path}'"
    except IOError as e:
        return f"Error: I/O error when reading file at '{file_path}' - {str(e)}"

    # Step 3: Parse YAML Content
    try:
        data = yaml.safe_load(yaml_content)
    except yaml.YAMLError as e:
        return f"Error: Invalid YAML content - {str(e)}"

    # If YAML file is empty, safe_load returns None
    if data is None:
        data = {}

    # Step 4: Convert to JSON and Return
    try:
        json_string = json.dumps(data, indent=2, ensure_ascii=False)
        return json_string
    except TypeError as e:
        return f"Error: Failed to serialize YAML data to JSON - {str(e)}"

